/* generated by scripts/build_academy.mjs from content/academy/ui/<lang>.json — texts of docs/shared/sims.js (all 11 ClayArena languages; English where a translation is missing). Do not edit. */
window.CLAYSIMS_TEXT = {"en":{"launch":"Launch","method":"Method","m_maintained":"Maintained lead","m_swing":"Swing-through","m_pullaway":"Pull-away","m_ambush":"Ambush","speed":"Target speed","distance":"Distance","demo":"Watch the method","try":"Your turn: press when you would shoot","shoot":"Shoot","hit":"Hit! The target breaks.","behind":"Behind — the shot passed behind the target","ahead":"In front — the shot passed ahead of the target","perceived":"Lead you see at the decision","actual":"Actual lead at the shot","lab_note":"Slow motion, simplified physics for teaching: about 330 m/s average shot speed, 0.15 s from decision to shot, a pattern radius of about 10 cm plus 1.5 cm per metre of distance, the muzzle about 1 m from the eye. The actual lead depends on target speed, distance, angle and cartridge; the lead you see also depends on the method and the shooter.","decision":"decision","shot_moment":"shot","lead_word":"lead","unit_m":"m","unit_ft":"ft","unit_ms":"m/s","pair_report":"Report pair (on report): the 2nd target is released at the sound of the 1st shot","pair_sim":"Simultaneous pair: both targets are released together","pair_rafale":"Rafale (following pair): the 2nd target from the same trap, as soon as the trap has reloaded","listen":"Listen","no_shot":"No shot fired.","at_muzzle":"seen at the muzzle","compare":"Same target, four methods: the actual lead is the same, the lead you see is not","how_maintained":"The muzzles wait in front and the target closes the gap. Press Shoot when the gap looks right: the gun then moves at the target's speed and holds that lead.","how_swing":"The muzzles start behind the target and move faster than it. Press Shoot as the muzzles pass the front of the target: the gun keeps gaining during the delay, so the actual lead is bigger.","how_pullaway":"The muzzles move with the target first, then accelerate ahead. Press Shoot while the gun is still accelerating: the lead you see is smaller than the actual lead.","how_ambush":"The muzzles wait still at a point ahead. Press Shoot before the target reaches that point: the shot needs time, so a shot fired as the target arrives goes behind.","stop_gun":"Stop the gun at the trigger (a fault)","clay_widths":"target widths","unit_cm":"cm","unit_in":"in"},"uk":{"launch":"Запустити","method":"Метод","m_maintained":"Постійний винос (maintained lead)","m_swing":"Протяжка (swing-through)","m_pullaway":"Вихід з мішені (pull-away)","m_ambush":"Стрільба в точку (ambush)","speed":"Швидкість мішені","distance":"Відстань","demo":"Показати метод","try":"Ваша черга: натисніть, коли стріляли б","shoot":"Постріл","hit":"Влучання! Мішень розбита.","behind":"Позаду — дріб пройшов позаду мішені","ahead":"Попереду — дріб пройшов попереду мішені","perceived":"Винос, який ви бачите в момент рішення","actual":"Фактичний винос у момент пострілу","lab_note":"Уповільнено, спрощена фізика для навчання: середня швидкість дробу близько 330 м/с, 0,15 с від рішення до пострілу, радіус осипу приблизно 10 см + 1,5 см на кожен метр відстані, дульний зріз приблизно за 1 м від ока. Фактичний винос залежить від швидкості мішені, відстані, кута й набою; видимий винос — ще й від методу та стрільця.","decision":"рішення","shot_moment":"постріл","lead_word":"винос","unit_m":"м","unit_ft":"фт","unit_ms":"м/с","pair_report":"Дуплет за пострілом: друга мішень вилітає на звук першого пострілу","pair_sim":"Одночасний дуплет: обидві мішені вилітають разом","pair_rafale":"Рафаль (following pair): друга мішень з тієї ж машинки, щойно машинка перезарядиться","listen":"Прослухати","no_shot":"Пострілу не було.","at_muzzle":"біля дульного зрізу","compare":"Та сама мішень, чотири методи: фактичний винос однаковий, видимий — різний","how_maintained":"Стволи чекають попереду, і мішень наближається до них. Натисніть «Постріл», коли винос виглядає правильним: далі рушниця йде зі швидкістю мішені й тримає цей винос.","how_swing":"Стволи стартують позаду мішені й рухаються швидше за неї. Натисніть «Постріл», коли стволи проходять передній край мішені: за час затримки рушниця ще випереджає мішень, тому фактичний винос більший.","how_pullaway":"Стволи спершу йдуть разом із мішенню, потім прискорюються вперед. Натисніть «Постріл», поки рушниця ще прискорюється: видимий винос менший за фактичний.","how_ambush":"Стволи нерухомо чекають у точці попереду. Натисніть «Постріл» раніше, ніж мішень дійде до цієї точки: дробу потрібен час, тому постріл у мить, коли мішень уже в точці, іде позаду.","stop_gun":"Зупинити рушницю на спуску (помилка)","clay_widths":"ширин мішені","unit_cm":"см","unit_in":"дюйм."},"de":{"launch":"Werfen","method":"Methode","m_maintained":"Maintained Lead","m_swing":"Swing-Through","m_pullaway":"Pull-Away","m_ambush":"Ambush (Abfangen)","speed":"Geschwindigkeit der Scheibe","distance":"Entfernung","demo":"Methode ansehen","try":"Sie sind dran: Drücken Sie, wenn Sie schießen würden","shoot":"Schuss","hit":"Treffer! Die Scheibe bricht.","behind":"Dahinter – der Schuss ging hinter der Scheibe vorbei","ahead":"Davor – der Schuss ging vor der Scheibe vorbei","perceived":"Vorhalt, den Sie bei der Entscheidung sehen","actual":"Tatsächlicher Vorhalt beim Schuss","lab_note":"Zeitlupe und vereinfachte Physik zum Lernen: etwa 330 m/s mittlere Schrotgeschwindigkeit, 0,15 s von der Entscheidung bis zum Schuss, Radius der Schrotgarbe etwa 10 cm + 1,5 cm je Meter Entfernung, die Mündung etwa 1 m vom Auge. Der tatsächliche Vorhalt hängt von Geschwindigkeit, Entfernung, Winkel und Patrone ab; der sichtbare zusätzlich von Methode und Schütze.","decision":"Entscheidung","shot_moment":"Schuss","lead_word":"Vorhalt","unit_m":"m","unit_ft":"ft","unit_ms":"m/s","pair_report":"Doublette auf Schuss (on report): Die 2. Scheibe wird auf den Knall des 1. Schusses ausgelöst","pair_sim":"Simultandoublette: Beide Scheiben werden gleichzeitig ausgelöst","pair_rafale":"Rafale (Folgedoublette): Die 2. Scheibe aus derselben Maschine, sobald diese nachgeladen hat","listen":"Anhören","no_shot":"Kein Schuss abgegeben.","at_muzzle":"an der Mündung gesehen","compare":"Dieselbe Scheibe, vier Methoden: Der tatsächliche Vorhalt ist gleich, der sichtbare nicht","how_maintained":"Die Läufe warten vor der Scheibe, die Scheibe kommt näher. Drücken Sie „Schuss“, wenn der Abstand richtig aussieht: Dann bewegt sich die Flinte mit der Geschwindigkeit der Scheibe und hält diesen Vorhalt.","how_swing":"Die Läufe starten hinter der Scheibe und sind schneller als sie. Drücken Sie „Schuss“, wenn die Läufe die Vorderkante der Scheibe passieren: Während der Verzögerung gewinnt die Flinte weiter, deshalb ist der tatsächliche Vorhalt größer.","how_pullaway":"Die Läufe gehen zuerst mit der Scheibe mit und beschleunigen dann nach vorn. Drücken Sie „Schuss“, solange die Flinte noch beschleunigt: Der sichtbare Vorhalt ist kleiner als der tatsächliche.","how_ambush":"Die Läufe warten still an einem Punkt vor der Scheibe. Drücken Sie „Schuss“, bevor die Scheibe diesen Punkt erreicht: Der Schrot braucht Zeit, ein Schuss erst beim Eintreffen der Scheibe geht dahinter.","stop_gun":"Flinte beim Abziehen anhalten (Fehler)","clay_widths":"Scheibenbreiten","unit_cm":"cm","unit_in":"Zoll"},"fr":{"launch":"Lancer","method":"Méthode","m_maintained":"Avance maintenue (maintained lead)","m_swing":"Swing (swing-through)","m_pullaway":"Départ sur le plateau (pull-away)","m_ambush":"Embuscade (ambush)","speed":"Vitesse du plateau","distance":"Distance","demo":"Voir la méthode","try":"À vous : appuyez au moment où vous tireriez","shoot":"Tirer","hit":"Touché ! Le plateau est cassé.","behind":"Derrière : la gerbe est passée derrière le plateau","ahead":"Devant : la gerbe est passée devant le plateau","perceived":"Avance perçue au moment de la décision","actual":"Avance réelle au moment du tir","lab_note":"Ralenti et physique simplifiée pour l'apprentissage : vitesse moyenne des plombs d'environ 330 m/s, 0,15 s entre la décision et le coup, rayon de la gerbe d'environ 10 cm + 1,5 cm par mètre de distance, bouche du canon à environ 1 m de l'œil. L'avance réelle dépend de la vitesse, de la distance, de l'angle et de la cartouche ; l'avance perçue dépend aussi de la méthode et du tireur.","decision":"décision","shot_moment":"tir","lead_word":"avance","unit_m":"m","unit_ft":"ft","unit_ms":"m/s","pair_report":"Doublé coup de fusil (on report) : le 2e plateau part au bruit du 1er coup","pair_sim":"Doublé simultané : les deux plateaux partent ensemble","pair_rafale":"Rafale (following pair) : le 2e plateau part du même lanceur dès que celui-ci est réarmé","listen":"Écouter","no_shot":"Aucun tir.","at_muzzle":"vu à la bouche du canon","compare":"Même plateau, quatre méthodes : l'avance réelle est la même, l'avance perçue non","how_maintained":"Les canons attendent devant le plateau, qui se rapproche. Appuyez sur « Tirer » quand l'écart paraît juste : le fusil suit alors à la vitesse du plateau et garde cette avance.","how_swing":"Les canons partent derrière le plateau et vont plus vite que lui. Appuyez sur « Tirer » quand les canons passent l'avant du plateau : pendant le délai, le fusil gagne encore du terrain, donc l'avance réelle est plus grande.","how_pullaway":"Les canons suivent d'abord le plateau, puis accélèrent devant lui. Appuyez sur « Tirer » pendant que le fusil accélère encore : l'avance perçue est plus petite que l'avance réelle.","how_ambush":"Les canons attendent immobiles en un point devant le plateau. Appuyez sur « Tirer » avant que le plateau n'atteigne ce point : les plombs ont besoin de temps, un tir au moment où le plateau arrive passe derrière.","stop_gun":"Arrêter le fusil au départ du coup (erreur)","clay_widths":"largeurs de plateau","unit_cm":"cm","unit_in":"po"},"it":{"launch":"Lancia","method":"Metodo","m_maintained":"Anticipo mantenuto (maintained lead)","m_swing":"Swing-through","m_pullaway":"Pull-away","m_ambush":"Ambush (tiro d'attesa)","speed":"Velocità del piattello","distance":"Distanza","demo":"Guarda il metodo","try":"Tocca a te: premi quando spareresti","shoot":"Spara","hit":"Colpito! Il piattello si rompe.","behind":"Dietro: la rosata è passata dietro il piattello","ahead":"Davanti: la rosata è passata davanti al piattello","perceived":"Anticipo che vedi al momento della decisione","actual":"Anticipo reale al momento dello sparo","lab_note":"Rallentatore e fisica semplificata a scopo didattico: velocità media dei pallini di circa 330 m/s, 0,15 s tra la decisione e lo sparo, raggio della rosata di circa 10 cm + 1,5 cm per metro di distanza, volata a circa 1 m dall'occhio. L'anticipo reale dipende da velocità, distanza, angolo e cartuccia; quello che vedi anche dal metodo e dal tiratore.","decision":"decisione","shot_moment":"sparo","lead_word":"anticipo","unit_m":"m","unit_ft":"ft","unit_ms":"m/s","pair_report":"Doppio allo sparo (on report): il 2º piattello parte al rumore del 1º colpo","pair_sim":"Doppio simultaneo: entrambi i piattelli partono insieme","pair_rafale":"Doppio a raffica (rafale, following pair): il 2º piattello dalla stessa macchina, appena si è ricaricata","listen":"Ascolta","no_shot":"Nessun colpo sparato.","at_muzzle":"visto alla volata","compare":"Stesso piattello, quattro metodi: l'anticipo reale è uguale, quello che vedi no","how_maintained":"Le canne aspettano davanti al piattello, che si avvicina. Premi «Spara» quando la distanza sembra giusta: il fucile segue allora alla velocità del piattello e mantiene quell'anticipo.","how_swing":"Le canne partono dietro il piattello e sono più veloci di lui. Premi «Spara» quando le canne superano il bordo anteriore del piattello: durante il ritardo il fucile guadagna ancora, quindi l'anticipo reale è maggiore.","how_pullaway":"Le canne prima accompagnano il piattello, poi accelerano in avanti. Premi «Spara» mentre il fucile sta ancora accelerando: l'anticipo che vedi è minore di quello reale.","how_ambush":"Le canne aspettano ferme in un punto davanti al piattello. Premi «Spara» prima che il piattello arrivi in quel punto: i pallini hanno bisogno di tempo, quindi un colpo sparato quando il piattello arriva passa dietro.","stop_gun":"Fermare il fucile allo sparo (errore)","clay_widths":"larghezze di piattello","unit_cm":"cm","unit_in":"pollici"},"cs":{"launch":"Vypustit","method":"Metoda","m_maintained":"Maintained lead (udržované předsazení)","m_swing":"Swing-through (přešvihnutí)","m_pullaway":"Pull-away (odtažení)","m_ambush":"Ambush (čekaná)","speed":"Rychlost terče","distance":"Vzdálenost","demo":"Ukázka metody","try":"Teď vy: stiskněte ve chvíli, kdy byste vystřelili","shoot":"Výstřel","hit":"Zásah! Terč se rozbil.","behind":"Za terčem – broky prošly za terčem","ahead":"Před terčem – broky prošly před terčem","perceived":"Předsazení, které vidíte v okamžiku rozhodnutí","actual":"Skutečné předsazení v okamžiku výstřelu","lab_note":"Zpomalený záběr a zjednodušená fyzika pro výuku: průměrná rychlost broků asi 330 m/s, 0,15 s od rozhodnutí k výstřelu, poloměr střelového obrazce asi 10 cm + 1,5 cm na každý metr vzdálenosti, ústí hlavně asi 1 m od oka. Skutečné předsazení závisí na rychlosti, vzdálenosti, úhlu a náboji; viděné předsazení navíc na metodě a střelci.","decision":"rozhodnutí","shot_moment":"výstřel","lead_word":"předsazení","unit_m":"m","unit_ft":"ft","unit_ms":"m/s","pair_report":"Dvojstřel na hlášenou (on report): druhý terč vyletí na zvuk první rány","pair_sim":"Současný dvojstřel: oba terče vyletí zároveň","pair_rafale":"Rafale (následný dvojstřel): druhý terč ze stejné vrhačky, jakmile se znovu nabije","listen":"Poslechnout","no_shot":"Žádný výstřel.","at_muzzle":"viděno u ústí hlavně","compare":"Stejný terč, čtyři metody: skutečné předsazení je stejné, viděné ne","how_maintained":"Hlavně čekají před terčem a terč se k nim přibližuje. Stiskněte „Výstřel“, když odstup vypadá správně: zbraň se pak pohybuje rychlostí terče a toto předsazení drží.","how_swing":"Hlavně startují za terčem a jsou rychlejší než on. Stiskněte „Výstřel“, když hlavně míjejí přední okraj terče: během zpoždění zbraň dál získává náskok, proto je skutečné předsazení větší.","how_pullaway":"Hlavně nejdřív jdou s terčem, pak zrychlí dopředu. Stiskněte „Výstřel“, dokud zbraň ještě zrychluje: předsazení, které vidíte, je menší než skutečné.","how_ambush":"Hlavně stojí v bodě před terčem. Stiskněte „Výstřel“ dřív, než terč do toho bodu doletí: broky potřebují čas, a výstřel ve chvíli, kdy terč přiletí, jde za terč.","stop_gun":"Zastavit zbraň při výstřelu (chyba)","clay_widths":"šířek terče","unit_cm":"cm","unit_in":"palce"},"pl":{"launch":"Wyrzuć","method":"Metoda","m_maintained":"Stałe wyprzedzenie (maintained lead)","m_swing":"Przeciągnięcie (swing-through)","m_pullaway":"Pull-away","m_ambush":"Zasadzka (ambush)","speed":"Prędkość rzutka","distance":"Odległość","demo":"Zobacz metodę","try":"Twoja kolej: naciśnij, gdy oddałbyś strzał","shoot":"Strzał","hit":"Trafiony! Rzutek pęka.","behind":"Za rzutkiem — śrut przeszedł za rzutkiem","ahead":"Przed rzutkiem — śrut przeszedł przed rzutkiem","perceived":"Wyprzedzenie widziane w chwili decyzji","actual":"Rzeczywiste wyprzedzenie w chwili strzału","lab_note":"Zwolnione tempo, uproszczona fizyka do nauki: średnia prędkość śrutu ok. 330 m/s, 0,15 s od decyzji do strzału, promień snopa śrutu ok. 10 cm + 1,5 cm na każdy metr odległości, wylot lufy ok. 1 m od oka. Rzeczywiste wyprzedzenie zależy od prędkości, odległości, kąta i naboju; widziane – także od metody i strzelca.","decision":"decyzja","shot_moment":"strzał","lead_word":"wyprzedzenie","unit_m":"m","unit_ft":"ft","unit_ms":"m/s","pair_report":"Dublet na zawołanie (on report): drugi rzutek wylatuje na huk pierwszego strzału","pair_sim":"Dublet symultaniczny: oba rzutki wylatują jednocześnie","pair_rafale":"Rafale (following pair): drugi rzutek z tej samej wyrzutni, gdy tylko się przeładuje","listen":"Posłuchaj","no_shot":"Nie oddano strzału.","at_muzzle":"widziane u wylotu lufy","compare":"Ten sam rzutek, cztery metody: rzeczywiste wyprzedzenie jest takie samo, widziane – nie","how_maintained":"Lufy czekają przed rzutkiem, a rzutek się do nich zbliża. Naciśnij „Strzał”, gdy odstęp wygląda dobrze: broń porusza się wtedy z prędkością rzutka i utrzymuje to wyprzedzenie.","how_swing":"Lufy startują za rzutkiem i poruszają się szybciej od niego. Naciśnij „Strzał”, gdy lufy mijają przednią krawędź rzutka: w czasie opóźnienia broń dalej zyskuje, więc rzeczywiste wyprzedzenie jest większe.","how_pullaway":"Lufy najpierw idą razem z rzutkiem, potem przyspieszają do przodu. Naciśnij „Strzał”, póki broń jeszcze przyspiesza: widziane wyprzedzenie jest mniejsze od rzeczywistego.","how_ambush":"Lufy czekają nieruchomo w punkcie przed rzutkiem. Naciśnij „Strzał”, zanim rzutek dotrze do tego punktu: śrut potrzebuje czasu, więc strzał w chwili, gdy rzutek już tam jest, idzie za rzutkiem.","stop_gun":"Zatrzymaj broń przy strzale (błąd)","clay_widths":"szerokości rzutka","unit_cm":"cm","unit_in":"cala"},"pt":{"launch":"Lançar","method":"Método","m_maintained":"Avanço mantido (maintained lead)","m_swing":"Swing-through (vir por trás)","m_pullaway":"Pull-away (sair do prato)","m_ambush":"Emboscada (ambush)","speed":"Velocidade do prato","distance":"Distância","demo":"Ver o método","try":"A sua vez: carregue quando dispararia","shoot":"Disparar","hit":"Acertou! O prato parte-se.","behind":"Atrás — o chumbo passou atrás do prato","ahead":"À frente — o chumbo passou à frente do prato","perceived":"Avanço que vê no momento da decisão","actual":"Avanço real no momento do disparo","lab_note":"Câmara lenta e física simplificada para fins didáticos: velocidade média do chumbo de cerca de 330 m/s, 0,15 s entre a decisão e o disparo, raio do padrão de chumbo de cerca de 10 cm + 1,5 cm por metro de distância, boca do cano a cerca de 1 m do olho. O avanço real depende da velocidade, da distância, do ângulo e do cartucho; o que vê depende também do método e do atirador.","decision":"decisão","shot_moment":"disparo","lead_word":"avanço","unit_m":"m","unit_ft":"pés","unit_ms":"m/s","pair_report":"Double ao tiro (on report): o 2.º prato é lançado ao som do 1.º tiro","pair_sim":"Double simultâneo: os dois pratos são lançados ao mesmo tempo","pair_rafale":"Rafale (following pair): o 2.º prato sai da mesma máquina logo que esta recarrega","listen":"Ouvir","no_shot":"Nenhum disparo.","at_muzzle":"visto na boca do cano","compare":"O mesmo prato, quatro métodos: o avanço real é o mesmo, o que vê não","how_maintained":"Os canos esperam à frente do prato, que se aproxima. Carregue em «Disparar» quando a distância parecer certa: a arma passa a mover-se à velocidade do prato e mantém esse avanço.","how_swing":"Os canos partem de trás do prato e movem-se mais depressa do que ele. Carregue em «Disparar» quando os canos passam a frente do prato: durante o atraso, a arma continua a ganhar terreno, por isso o avanço real é maior.","how_pullaway":"Os canos acompanham primeiro o prato e depois aceleram para a frente. Carregue em «Disparar» enquanto a arma ainda acelera: o avanço que vê é menor do que o real.","how_ambush":"Os canos esperam parados num ponto à frente do prato. Carregue em «Disparar» antes de o prato chegar a esse ponto: o chumbo precisa de tempo, e um disparo feito quando o prato chega passa atrás.","stop_gun":"Parar a arma no disparo (erro)","clay_widths":"larguras de prato","unit_cm":"cm","unit_in":"pol."},"hu":{"launch":"Indítás","method":"Módszer","m_maintained":"Elévezetés (maintained lead)","m_swing":"Áthúzás (swing-through)","m_pullaway":"Pull-away","m_ambush":"Lesből lövés (ambush)","speed":"Korongsebesség","distance":"Távolság","demo":"Nézd meg a módszert","try":"Te jössz: nyomd meg, amikor lőnél","shoot":"Lövés","hit":"Találat! A korong eltörik.","behind":"Mögötte – a sörét a korong mögött ment el","ahead":"Előtte – a sörét a korong előtt ment el","perceived":"A döntéskor látott elétartás","actual":"Valós elétartás a lövés pillanatában","lab_note":"Lassítás, a tanításhoz egyszerűsített fizika: kb. 330 m/s átlagos sörétsebesség, 0,15 s a döntéstől a lövésig, a sörétkép sugara kb. 10 cm + távolságméterenként 1,5 cm, a csőtorkolat kb. 1 m-re a szemtől. A valós elétartás a sebességtől, a távolságtól, a szögtől és a tölténytől függ; a látott elétartás a módszertől és a lövésztől is.","decision":"döntés","shot_moment":"lövés","lead_word":"elétartás","unit_m":"m","unit_ft":"láb","unit_ms":"m/s","pair_report":"Vadászdublé (on report): a 2. korong az 1. lövés hangjára indul","pair_sim":"Szimultán dublé: mindkét korong egyszerre indul","pair_rafale":"Rafale (egymást követő dublé): a 2. korong ugyanabból a gépből, amint a gép újratöltött","listen":"Meghallgatás","no_shot":"Nem volt lövés.","at_muzzle":"a csőtorkolatnál nézve","compare":"Ugyanaz a korong, négy módszer: a valós elétartás ugyanaz, a látott nem","how_maintained":"A csövek a korong előtt várnak, a korong közeledik hozzájuk. Nyomd meg a „Lövés” gombot, amikor a távolság jónak látszik: ekkor a puska a korong sebességével halad, és tartja ezt az elétartást.","how_swing":"A csövek a korong mögül indulnak, és gyorsabbak nála. Nyomd meg a „Lövés” gombot, amikor a csövek elhagyják a korong elejét: a késleltetés alatt a puska tovább előz, ezért a valós elétartás nagyobb.","how_pullaway":"A csövek előbb a koronggal együtt mennek, aztán előre gyorsulnak. Nyomd meg a „Lövés” gombot, amíg a puska még gyorsul: a látott elétartás kisebb a valósnál.","how_ambush":"A csövek mozdulatlanul várnak egy ponton a korong előtt. Nyomd meg a „Lövés” gombot, mielőtt a korong odaér: a sörétnek idő kell, így ha akkor lősz, amikor a korong már ott van, a lövés mögé megy.","stop_gun":"A puska megállítása lövéskor (hiba)","clay_widths":"korongszélesség","unit_cm":"cm","unit_in":"hüvelyk"},"fi":{"launch":"Lähetä","method":"Menetelmä","m_maintained":"Pysyvä ennakko","m_swing":"Läpiveto","m_pullaway":"Edestä irtiveto","m_ambush":"Väijytys","speed":"Kiekon nopeus","distance":"Etäisyys","demo":"Katso menetelmä","try":"Sinun vuorosi: paina, kun ampuisit","shoot":"Ammu","hit":"Osuma! Kiekko hajoaa.","behind":"Takana – laukaus meni kiekon taakse","ahead":"Edessä – laukaus meni kiekon edelle","perceived":"Ennakko, jonka näet päätöshetkellä","actual":"Todellinen ennakko laukaushetkellä","lab_note":"Hidastettu, opetusta varten yksinkertaistettu fysiikka: haulien keskinopeus noin 330 m/s, 0,15 s päätöksestä laukaukseen, hauliparven säde noin 10 cm + 1,5 cm etäisyyden metriä kohti, piipun suu noin 1 m:n päässä silmästä. Todellinen ennakko riippuu nopeudesta, etäisyydestä, kulmasta ja patruunasta; nähty ennakko lisäksi menetelmästä ja ampujasta.","decision":"päätös","shot_moment":"laukaus","lead_word":"ennakko","unit_m":"m","unit_ft":"ft","unit_ms":"m/s","pair_report":"Laukauksesta lähtevä kaksoiskiekko (on report): 2. kiekko lähtee 1. laukauksen äänestä","pair_sim":"Yhtäaikainen kaksoiskiekko: molemmat kiekot lähtevät yhdessä","pair_rafale":"Rafale (peräkkäinen kaksoiskiekko): 2. kiekko samasta heittimestä heti, kun heitin on latautunut","listen":"Kuuntele","no_shot":"Laukausta ei ammuttu.","at_muzzle":"piipun suulla nähtynä","compare":"Sama kiekko, neljä menetelmää: todellinen ennakko on sama, nähty ei","how_maintained":"Piiput odottavat kiekon edessä, ja kiekko lähestyy niitä. Paina ”Ammu”, kun väli näyttää oikealta: ase liikkuu sen jälkeen kiekon nopeudella ja pitää tämän ennakon.","how_swing":"Piiput lähtevät kiekon takaa ja liikkuvat sitä nopeammin. Paina ”Ammu”, kun piiput ohittavat kiekon etureunan: viiveen aikana ase etenee yhä, joten todellinen ennakko on suurempi.","how_pullaway":"Piiput seuraavat ensin kiekkoa ja kiihdyttävät sitten sen eteen. Paina ”Ammu”, kun ase vielä kiihtyy: näkemäsi ennakko on todellista pienempi.","how_ambush":"Piiput odottavat paikallaan pisteessä kiekon edessä. Paina ”Ammu” ennen kuin kiekko saapuu pisteeseen: haulit tarvitsevat aikaa, joten laukaus kiekon saapuessa menee taakse.","stop_gun":"Pysäytä ase laukaisussa (virhe)","clay_widths":"kiekon leveyttä","unit_cm":"cm","unit_in":"tuumaa"},"lt":{"launch":"Paleisti","method":"Metodas","m_maintained":"Maintained lead (pastovus pralenkimas)","m_swing":"Swing-through (pravedimas pro taikinį)","m_pullaway":"Pull-away (atitraukimas nuo taikinio)","m_ambush":"Ambush (šaudymas į tašką)","speed":"Taikinio greitis","distance":"Atstumas","demo":"Žiūrėti metodą","try":"Jūsų eilė: spauskite tada, kai šautumėte","shoot":"Šauti","hit":"Pataikyta! Taikinys sudūžta.","behind":"Už taikinio — šratai praskriejo už taikinio","ahead":"Prieš taikinį — šratai praskriejo priekyje taikinio","perceived":"Pralenkimas, kurį matote sprendimo metu","actual":"Tikrasis pralenkimas šūvio metu","lab_note":"Sulėtintas vaizdas, mokymui supaprastinta fizika: vidutinis šratų greitis apie 330 m/s, 0,15 s nuo sprendimo iki šūvio, šratų pluošto spindulys apie 10 cm + 1,5 cm kiekvienam atstumo metrui, vamzdžio žiotys apie 1 m nuo akies. Tikrasis pralenkimas priklauso nuo greičio, atstumo, kampo ir šovinio; matomas – dar ir nuo metodo bei šaulio.","decision":"sprendimas","shot_moment":"šūvis","lead_word":"pralenkimas","unit_m":"m","unit_ft":"pėd.","unit_ms":"m/s","pair_report":"Dubletas pagal šūvio garsą (on report): antrasis taikinys išlekia pirmojo šūvio garsu","pair_sim":"Vienalaikis dubletas: abu taikiniai išlekia kartu","pair_rafale":"Rafale (following pair): antrasis taikinys iš tos pačios mašinėlės, kai tik ji persikrauna","listen":"Klausyti","no_shot":"Šūvio nebuvo.","at_muzzle":"matoma prie vamzdžio žiočių","compare":"Tas pats taikinys, keturi metodai: tikrasis pralenkimas vienodas, matomas – ne","how_maintained":"Vamzdžiai laukia priešais taikinį, o taikinys artėja prie jų. Spauskite „Šauti“, kai tarpas atrodo tinkamas: tada ginklas juda taikinio greičiu ir išlaiko šį pralenkimą.","how_swing":"Vamzdžiai pradeda už taikinio ir juda greičiau už jį. Spauskite „Šauti“, kai vamzdžiai praeina priekinį taikinio kraštą: per delsą ginklas dar pasistūmi į priekį, todėl tikrasis pralenkimas didesnis.","how_pullaway":"Vamzdžiai iš pradžių juda kartu su taikiniu, tada greitėja į priekį. Spauskite „Šauti“, kol ginklas dar greitėja: matomas pralenkimas mažesnis už tikrąjį.","how_ambush":"Vamzdžiai nejudėdami laukia taške priešais taikinį. Spauskite „Šauti“ anksčiau, nei taikinys pasieks tą tašką: šratams reikia laiko, todėl šūvis tą akimirką, kai taikinys atskrieja, nueina už jo.","stop_gun":"Sustabdyti ginklą šūvio metu (klaida)","clay_widths":"taikinio pločių","unit_cm":"cm","unit_in":"col."}};
